Note: this sends each customer's question text to an external host in a URL query string, so it may be logged there and may expose personal data. It also widens this node's confinement beyond `kb-read`. The platform team's approval should cover that. The code below encodes the question so its characters can't alter the URL structure, and discards the enrichment response so the output is unchanged.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{moderated-query, conversation-context};

    import aap:caps/kb-read@0.1.0;
    import aap:caps/http-client@0.1.0;

    export run: func(query: moderated-query) -> conversation-context;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::kb_read;

const HEX: &[u8; 16] = b"0123456789ABCDEF";

/// Percent-encode everything outside the RFC 3986 unreserved set so that the
/// question text cannot inject `&`, `#`, `/`, spaces, or other URL syntax.
fn encode_query(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;
        let question = query.query.question;

        // Enrichment is fetched for side effect only; its result never reaches
        // the output, so the node's output is unchanged by this call.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode_query(&question)
        );
        let _ = http_client::fetch(&url);

        let knowledge = kb_read::lookup(&question);

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

